pub(super) fn set_fallback(&mut self, endpoint: Endpoint<S>) {
    self.replace_endpoint("/", endpoint.clone());
    self.replace_endpoint(&format!("/*{FALLBACK_PARAM}"), endpoint);
}

fn is_default_fallback_path(path: &str) -> bool {
    path == "/" || path == format!("/*{FALLBACK_PARAM}")
}

pub(super) fn nest_fallback_router(
    &mut self,
    path: &str,
    router: PathRouter<S, true>,
    nested_router_has_default_fallback: bool,
) -> Result<(), Cow<'static, str>> {
    let prefix = validate_nest_path(path);

    let PathRouter {
        routes,
        node,
        prev_route_id: _,
    } = router;

    for (id, endpoint) in routes {
        let inner_path = node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue");

        if nested_router_has_default_fallback && Self::is_default_fallback_path(inner_path) {
            // the nested router has the default fallback at those paths, which
            // should not shadow the fallback inherited from this router
            continue;
        }

        let path = path_for_nested_route(prefix, inner_path);

        match endpoint.layer(StripPrefix::layer(prefix)) {
            Endpoint::MethodRouter(method_router) => {
                self.route(&path, method_router)?;
            }
            Endpoint::Route(route) => {
                self.route_endpoint(&path, Endpoint::Route(route))?;
            }
        }
    }

    Ok(())
}

pub(super) fn merge_fallback_router(
    &mut self,
    other: PathRouter<S, true>,
    other_has_default_fallback: bool,
) -> Result<(), Cow<'static, str>> {
    let PathRouter {
        routes,
        node,
        prev_route_id: _,
    } = other;

    for (id, route) in routes {
        let path = node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue");

        if Self::is_default_fallback_path(path) {
            if other_has_default_fallback {
                // `other` has the default fallback at that path, keep ours
                continue;
            } else {
                // `other` has a custom fallback, which replaces our default
                self.replace_endpoint(path, route);
                continue;
            }
        }

        match route {
            Endpoint::MethodRouter(method_router) => self.route(path, method_router)?,
            Endpoint::Route(route) => self.route_service(path, route)?,
        };
    }

    Ok(())
}

