    (true, true) => {
        panic_on_err!(self.fallback_router.merge_fallback_router(other_fallback, true));
    }
    // self has default fallback, other has a custom fallback
    (true, false) => {
        panic_on_err!(self.fallback_router.merge_fallback_router(other_fallback, false));
        self.default_fallback = false;
    }
    // self has a custom fallback, other has a default.
    // `other` may still have nested fallbacks which must be kept
    (false, true) => {
        panic_on_err!(self.fallback_router.merge_fallback_router(other_fallback, true));
    }
    // both have a custom fallback, not allowed
    (false, false) => {
        panic!("Cannot merge two `Router`s that both have a fallback")
    }
};

