use axum::{routing::get, Router};
use tower::ServiceExt;
use http::{Request, StatusCode};
use axum::body::Body;

#[tokio::test]
async fn issue_snippet() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new()
        .nest("/nested", nested_routes)
        .merge(other_router);

    let res = app
        .clone()
        .oneshot(Request::get("/other").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    assert_eq!(String::from_utf8(to_bytes(res).await).unwrap(), "other");

    let res = app
        .clone()
        .oneshot(Request::get("/nested/some-route").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(String::from_utf8(to_bytes(res).await).unwrap(), "nested");

    let res = app
        .oneshot(Request::get("/nested/foo").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(String::from_utf8(to_bytes(res).await).unwrap(), "fallback");
}

async fn to_bytes(res: axum::response::Response) -> Vec<u8> {
    use http_body_util::BodyExt;
    res.into_body().collect().await.unwrap().to_bytes().to_vec()
}

use axum::{body::Body, http::Request, routing::get, Router};
use tower::ServiceExt;

#[tokio::test]
async fn issue_snippet() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new()
        .nest("/nested", nested_routes)
        .merge(other_router);

    let res = app
        .clone()
        .oneshot(Request::builder().uri("/other").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), 200);
    assert_eq!(hyper::body::to_bytes(res.into_body()).await.unwrap(), "other");

    let res = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/nested/some-route")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        hyper::body::to_bytes(res.into_body()).await.unwrap(),
        "nested"
    );

    let res = app
        .oneshot(
            Request::builder()
                .uri("/nested/foo")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        hyper::body::to_bytes(res.into_body()).await.unwrap(),
        "fallback"
    );
}
